    code: 'import jax\nimport optax\n\nrecording = voltages[0]                                  # the spike to match\ncell.branch(0).make_trainable("HH_gNa", init_val=0.07)  # start wrong\ncell.branch(0).make_trainable("HH_gK", init_val=0.02)\nparams = cell.get_parameters()\n\ndef loss(params):\n    v = jx.integrate(cell, params=params, delta_t=0.025)[0]\n    return ((v - recording) ** 2).mean()\n\ngrad = jax.jit(jax.value_and_grad(loss))\noptimizer = optax.adam(learning_rate=0.002)\nstate = optimizer.init(params)\nfor step in range(101):\n    value, g = grad(params)\n    gna, gk = params[0]["HH_gNa"][0], params[1]["HH_gK"][0]\n    if step % 20 == 0:\n        print(f"{step:3}  loss {value:7.3f}  gNa {gna:.4f}  gK {gk:.4f}")\n    updates, state = optimizer.update(g, state)\n    params = optax.apply_updates(params, updates)',
